FUNCTION_BLOCK FB_CAES_CavernRecuperatorBalance
(* ========================================================================================= *)
(* LUMINA CYBER-PHYSICAL SYSTEMS ARCHITECTURE - CAES TURBOMACHINERY CORE                     *)
(* MODULE: UNDERGROUND BEDDED/DOMAL SALT CAVERN PRESSURE LETDOWN & AIR RECUPERATOR BALANCE  *)
(* IEC 61131-3 INDUSTRIAL CONTROL CODE: HIGH-FIDELITY DETERMINISTIC IMPLEMENTATION          *)
(* SAFETY INTEGRITY LEVEL: SIL-3 ARCHITECTURE (IEC 61508 / IEC 61511 / ISA-84)               *)
(* FEATURES:                                                                                 *)
(*  1. Triple Modular Redundant (2oo3) Sensor Voting with Online Discrepancy Fault Analysis  *)
(*  2. Joule-Thomson Isenthalpic Throttling Cryo-Freezing Mitigation & Enthalpy Tracking      *)
(*  3. 2x2 Discrete State-Space Model Predictive Control (MPC) with Quadratic Cost Minima    *)
(*  4. Recuperator Tube-Sheet Thermal Stress & Thermal Gradient Rate Limiting (dT/dt)        *)
(*  5. 8-State Deterministic Execution Engine with Graceful 1oo2 Degradation & E-Trip Logic   *)
(* ========================================================================================= *)
VAR_INPUT
    bEnable                 : BOOL;     (* Process master enable supervisory permissive signal [-] *)
    bEmergencyTripPB        : BOOL;     (* Hardwired SIL-3 emergency trip push button (Active Low, True = Healthy) [-] *)
    rP_Cavern_A             : REAL;     (* Cavern wellhead hydrostatic pressure transducer Channel A [bar] *)
    rP_Cavern_B             : REAL;     (* Cavern wellhead hydrostatic pressure transducer Channel B [bar] *)
    rP_Cavern_C             : REAL;     (* Cavern wellhead hydrostatic pressure transducer Channel C [bar] *)
    rT_CavernAir            : REAL;     (* Raw salt cavern discharge air thermodynamic temperature [deg C] *)
    rP_HeaderActual         : REAL;     (* Regulated expansion turbine high-pressure header manifold pressure [bar] *)
    rP_HeaderSetpoint       : REAL;     (* Target regulated header pressure setpoint (Typically 40.0 - 46.0) [bar] *)
    rT_FlueGas_In           : REAL;     (* Low-pressure gas expander exhaust gas entering recuperator hot side [deg C] *)
    rT_Recuperator_A        : REAL;     (* Preheated air discharge temperature sensor Channel A [deg C] *)
    rT_Recuperator_B        : REAL;     (* Preheated air discharge temperature sensor Channel B [deg C] *)
    rT_Recuperator_C        : REAL;     (* Preheated air discharge temperature sensor Channel C [deg C] *)
    rM_TargetAirFlow        : REAL;     (* Active power generation air mass flow demand setpoint [kg/s] *)
    rPowerDemand_MW         : REAL;     (* Grid automatic generation control (AGC) active power demand [MW] *)
    rCycleTime_Sec          : REAL;     (* Deterministic PLC execution task scan cycle period [s] *)
END_VAR

VAR_OUTPUT
    rValve_PCV_Pos          : REAL;     (* High-pressure cavern letdown control valve actuator demand [%] (0.0 to 100.0) *)
    rValve_TCV_Bypass       : REAL;     (* Recuperator cold-side air thermal bypass damper actuator demand [%] (0.0 to 100.0) *)
    rT_AirToTurbine         : REAL;     (* 2oo3 validated preheated air admission temperature to HP turbine [deg C] *)
    rP_VotedCavern          : REAL;     (* 2oo3 median voted salt cavern storage wellhead pressure [bar] *)
    rM_ActualAirFlow        : REAL;     (* Instantaneous estimated cavern air discharge mass flow [kg/s] *)
    rRecuperatorDuty_MW     : REAL;     (* Calculated thermal energy rate transferred across recuperator [MW] *)
    rThermalStressRate      : REAL;     (* Real-time thermal gradient across recuperator heat transfer matrix [deg C/min] *)
    wSystemStatus           : WORD;     (* Hexadecimal bitfield of current automation sequencing state *)
    wDiagnosticAlarms       : DWORD;    (* 32-bit discrete diagnostic fault register and discrepancy flags *)
    bTripActive             : BOOL;     (* Master process shutdown trip latch status (True = Tripped) [-] *)
    bSystemReady            : BOOL;     (* Permissive handshake ready for expander admission valve unlatch [-] *)
END_VAR

VAR
    (* Automation Finite State Machine Step Control *)
    iState                  : INT := 0; (* 0=IDLE, 10=TMR_CHECK, 20=LETDOWN_RAMP, 30=RECUP_WARMUP, 40=AUTO_MPC_RUN, 50=DEGRADED, 60=SHUTDOWN, 99=TRIP *)

    (* 2oo3 Triple Modular Redundancy Internal Registers *)
    rDiff_P_AB              : REAL;     (* Delta pressure Channel A - B [bar] *)
    rDiff_P_BC              : REAL;     (* Delta pressure Channel B - C [bar] *)
    rDiff_P_CA              : REAL;     (* Delta pressure Channel C - A [bar] *)
    rDiff_T_AB              : REAL;     (* Delta temperature Channel A - B [deg C] *)
    rDiff_T_BC              : REAL;     (* Delta temperature Channel B - C [deg C] *)
    rDiff_T_CA              : REAL;     (* Delta temperature Channel C - A [deg C] *)
    bFault_P_A              : BOOL;     (* Pressure Channel A transducer drift fault flag *)
    bFault_P_B              : BOOL;     (* Pressure Channel B transducer drift fault flag *)
    bFault_P_C              : BOOL;     (* Pressure Channel C transducer drift fault flag *)
    bFault_T_A              : BOOL;     (* Temperature Channel A sensor drift fault flag *)
    bFault_T_B              : BOOL;     (* Temperature Channel B sensor drift fault flag *)
    bFault_T_C              : BOOL;     (* Temperature Channel C sensor drift fault flag *)

    (* Thermodynamic Gas Dynamics & Joule-Thomson Variables *)
    rJouleThomsonCoeff      : REAL := 0.235; (* Air JT expansion throttling cooling coefficient [deg C / bar] *)
    rDeltaP_Letdown         : REAL;          (* Pressure drop across wellhead throttling valve train [bar] *)
    rT_LetdownExitEstimated : REAL;          (* Computed post-throttling air temperature upstream of recuperator [deg C] *)
    rSpecificHeat_Cp        : REAL := 1.018; (* Mean isobaric specific heat capacity for compressed air [kJ / (kg * K)] *)
    rAirGasConstant_R       : REAL := 0.287; (* Specific gas constant for dry atmospheric air [kJ / (kg * K)] *)
    rFlowDischargeCoeff     : REAL := 0.82;  (* Calibrated letdown valve flow discharge sizing coefficient *)

    (* Recuperator Mechanical Thermal Fatigue Constraints *)
    rMaxThermalRate_C_Min   : REAL := 2.50;  (* Maximum permissible tube-to-shell temperature ramp rate [deg C / min] *)
    rT_RecupPrevScan        : REAL := 20.0;  (* Stored previous execution cycle temperature for backward difference derivative *)

    (* 2x2 Model Predictive Control (MPC) Discrete State-Space Model *)
    (* State Vector: x = [x1: Header Pressure Error (bar), x2: Recuperator Preheated Temperature Error (deg C)] *)
    (* Control Vector: u = [u1: Delta PCV Valve Demand (%), u2: Delta TCV Bypass Damper Demand (%)] *)
    (* Discrete State Space Model Matrices at Scan Cycle Ts: *)
    rA11                    : REAL := 0.9412; (* Header pressure decay pole reflecting piping volume accumulator dynamics *)
    rA12                    : REAL := 0.0018; (* Cross-coupling of air thermal expansion on header line pack *)
    rA21                    : REAL := -0.0210;(* Through-flow velocity convection cooling perturbation on recuperator heat transfer *)
    rA22                    : REAL := 0.9785; (* Heavy stainless-steel recuperator matrix thermal inertia dominant pole *)

    rB11                    : REAL := 0.2240; (* Direct letdown valve gain on manifold pressure [bar / % stroke] *)
    rB12                    : REAL := -0.0125;(* High-temperature bypass valve coupling on manifold pressure *)
    rB21                    : REAL := 0.0380; (* Forced convection mass flow transfer rate enhancement on air temperature *)
    rB22                    : REAL := -0.3850;(* Cold air bypass tempering effectiveness [deg C / % damper open] *)

    (* MPC Quadratic Objective Function Optimization Weighting Matrices (Diagonal Q and R) *)
    rWeight_Q_P             : REAL := 18.5;   (* Header pressure regulation quadratic penalty coefficient *)
    rWeight_Q_T             : REAL := 12.0;   (* Recuperator exit air temperature tracking penalty coefficient *)
    rWeight_R_PCV           : REAL := 1.75;   (* Letdown valve movement energy rate damping factor *)
    rWeight_R_TCV           : REAL := 1.10;   (* Recuperator thermal bypass valve movement damping factor *)

    (* MPC Optimization Internal Numerics & Gradient Projections *)
    rState_x1               : REAL;          (* Current manifold pressure error x1(k) [bar] *)
    rState_x2               : REAL;          (* Current recuperator temperature error x2(k) [deg C] *)
    rPred_x1_free           : REAL;          (* Free response prediction of manifold pressure error x1(k+1|k) *)
    rPred_x2_free           : REAL;          (* Free response prediction of temperature error x2(k+1|k) *)
    rHessian_11             : REAL;          (* Analytical Hessian diagonal element for PCV *)
    rHessian_22             : REAL;          (* Analytical Hessian diagonal element for TCV *)
    rDelta_u1_Optimal       : REAL;          (* Solved unconstrained optimal control step for letdown valve [%] *)
    rDelta_u2_Optimal       : REAL;          (* Solved unconstrained optimal control step for bypass damper [%] *)

    (* Internal Actuators Slew-Rate and Position Limiters *)
    rPCV_CurrentPos         : REAL := 0.0;   (* Integrated letdown valve stroke position [%] *)
    rTCV_CurrentPos         : REAL := 100.0; (* Integrated thermal bypass damper stroke position [%] *)
    rMaxSlewPCV_PerSec      : REAL := 4.0;   (* Maximum allowable letdown valve travel rate [% / s] *)
    rMaxSlewTCV_PerSec      : REAL := 6.0;   (* Maximum allowable thermal bypass travel rate [% / s] *)

    (* Timers, Ramps & Operational Tracking *)
    tStateTimer             : TON;           (* Generic multi-purpose state dwell and transition timer *)
    rTarget_TurbineTemp     : REAL := 535.0; (* High-efficiency turbine optimum admission temperature setpoint [deg C] *)
    rWarmupProgress_Pct     : REAL := 0.0;   (* Recuperator controlled thermal ramp progress index [%] *)
    rDensity_Actual         : REAL;          (* Calculated air density upstream of turbine [kg / m^3] *)
END_VAR

(* === SECTION 1: TRIPLE MODULAR REDUNDANCY (2oo3) VOTING AND FAULT DETECTION === *)
rDiff_P_AB := ABS(rP_Cavern_A - rP_Cavern_B);
rDiff_P_BC := ABS(rP_Cavern_B - rP_Cavern_C);
rDiff_P_CA := ABS(rP_Cavern_C - rP_Cavern_A);

(* Channel Disparity Fault Flags: 3.5 bar threshold *)
bFault_P_A := (rDiff_P_AB > 3.5) AND (rDiff_P_CA > 3.5);
bFault_P_B := (rDiff_P_AB > 3.5) AND (rDiff_P_BC > 3.5);
bFault_P_C := (rDiff_P_BC > 3.5) AND (rDiff_P_CA > 3.5);

(* Pressure Median Voting and Graceful Degradation *)
IF NOT bFault_P_A AND NOT bFault_P_B AND NOT bFault_P_C THEN
    (* All three sensors healthy: Strict median calculation *)
    IF (rP_Cavern_A >= rP_Cavern_B AND rP_Cavern_A <= rP_Cavern_C) OR (rP_Cavern_A <= rP_Cavern_B AND rP_Cavern_A >= rP_Cavern_C) THEN
        rP_VotedCavern := rP_Cavern_A;
    ELSIF (rP_Cavern_B >= rP_Cavern_A AND rP_Cavern_B <= rP_Cavern_C) OR (rP_Cavern_B <= rP_Cavern_A AND rP_Cavern_B >= rP_Cavern_C) THEN
        rP_VotedCavern := rP_Cavern_B;
    ELSE
        rP_VotedCavern := rP_Cavern_C;
    END_IF;
ELSIF bFault_P_A AND NOT bFault_P_B AND NOT bFault_P_C THEN
    (* Channel A faulted: degraded 1oo2 average of B and C *)
    rP_VotedCavern := (rP_Cavern_B + rP_Cavern_C) * 0.5;
ELSIF bFault_P_B AND NOT bFault_P_A AND NOT bFault_P_C THEN
    (* Channel B faulted: degraded 1oo2 average of A and C *)
    rP_VotedCavern := (rP_Cavern_A + rP_Cavern_C) * 0.5;
ELSIF bFault_P_C AND NOT bFault_P_A AND NOT bFault_P_B THEN
    (* Channel C faulted: degraded 1oo2 average of A and B *)
    rP_VotedCavern := (rP_Cavern_A + rP_Cavern_B) * 0.5;
ELSE
    (* Multiple sensor failure: clamp to safest channel reading *)
    rP_VotedCavern := rP_Cavern_A;
END_IF;

(* Recuperator Temperature 2oo3 Voting *)
rDiff_T_AB := ABS(rT_Recuperator_A - rT_Recuperator_B);
rDiff_T_BC := ABS(rT_Recuperator_B - rT_Recuperator_C);
rDiff_T_CA := ABS(rT_Recuperator_C - rT_Recuperator_A);

(* Channel Disparity Fault Flags: 12.0 deg C threshold *)
bFault_T_A := (rDiff_T_AB > 12.0) AND (rDiff_T_CA > 12.0);
bFault_T_B := (rDiff_T_AB > 12.0) AND (rDiff_T_BC > 12.0);
bFault_T_C := (rDiff_T_BC > 12.0) AND (rDiff_T_CA > 12.0);

IF NOT bFault_T_A AND NOT bFault_T_B AND NOT bFault_T_C THEN
    IF (rT_Recuperator_A >= rT_Recuperator_B AND rT_Recuperator_A <= rT_Recuperator_C) OR (rT_Recuperator_A <= rT_Recuperator_B AND rT_Recuperator_A >= rT_Recuperator_C) THEN
        rT_AirToTurbine := rT_Recuperator_A;
    ELSIF (rT_Recuperator_B >= rT_Recuperator_A AND rT_Recuperator_B <= rT_Recuperator_C) OR (rT_Recuperator_B <= rT_Recuperator_A AND rT_Recuperator_B >= rT_Recuperator_C) THEN
        rT_AirToTurbine := rT_Recuperator_B;
    ELSE
        rT_AirToTurbine := rT_Recuperator_C;
    END_IF;
ELSIF bFault_T_A AND NOT bFault_T_B AND NOT bFault_T_C THEN
    rT_AirToTurbine := (rT_Recuperator_B + rT_Recuperator_C) * 0.5;
ELSIF bFault_T_B AND NOT bFault_T_A AND NOT bFault_T_C THEN
    rT_AirToTurbine := (rT_Recuperator_A + rT_Recuperator_C) * 0.5;
ELSIF bFault_T_C AND NOT bFault_T_A AND NOT bFault_T_B THEN
    rT_AirToTurbine := (rT_Recuperator_A + rT_Recuperator_B) * 0.5;
ELSE
    rT_AirToTurbine := rT_Recuperator_A;
END_IF;

(* === SECTION 2: THERMODYNAMICS & JOULE-THOMSON ENTHALPY BALANCE === *)
rDeltaP_Letdown := rP_VotedCavern - rP_HeaderActual;
IF rDeltaP_Letdown < 0.0 THEN
    rDeltaP_Letdown := 0.0;
END_IF;

(* Isenthalpic throttling Joule-Thomson cooling prediction *)
rT_LetdownExitEstimated := rT_CavernAir - (rJouleThomsonCoeff * rDeltaP_Letdown);

(* High-pressure compressible gas mass flow through PCV *)
IF rT_CavernAir > -50.0 THEN
    rM_ActualAirFlow := rFlowDischargeCoeff * (rPCV_CurrentPos / 100.0) * rP_VotedCavern * SQRT(288.15 / (rT_CavernAir + 273.15)) * 1.42;
ELSE
    rM_ActualAirFlow := 0.0;
END_IF;

(* Transferred Recuperator Thermal Power [MW] *)
rRecuperatorDuty_MW := (rM_ActualAirFlow * rSpecificHeat_Cp * (rT_AirToTurbine - rT_LetdownExitEstimated)) / 1000.0;
IF rRecuperatorDuty_MW < 0.0 THEN
    rRecuperatorDuty_MW := 0.0;
END_IF;

(* Recuperator Tube Sheet Thermal Stress Rate (dT/dt) in deg C / min *)
IF rCycleTime_Sec > 0.001 THEN
    rThermalStressRate := ((rT_AirToTurbine - rT_RecupPrevScan) / rCycleTime_Sec) * 60.0;
    rT_RecupPrevScan := rT_AirToTurbine;
ELSE
    rThermalStressRate := 0.0;
END_IF;

(* === SECTION 3: 2x2 DISCRETE STATE-SPACE MODEL PREDICTIVE CONTROL (MPC) === *)
(* Error Coordinates relative to Target Setpoints *)
rState_x1 := rP_HeaderActual - rP_HeaderSetpoint;
rState_x2 := rT_AirToTurbine - rTarget_TurbineTemp;

(* One-Step Ahead Autonomous State Prediction x(k+1|k) = A * x(k) *)
rPred_x1_free := (rA11 * rState_x1) + (rA12 * rState_x2);
rPred_x2_free := (rA21 * rState_x1) + (rA22 * rState_x2);

(* Analytical Hessian Diagonal Elements for Quadratic Cost Minimization *)
rHessian_11 := 2.0 * ((rB11 * rB11 * rWeight_Q_P) + (rB21 * rB21 * rWeight_Q_T) + rWeight_R_PCV);
rHessian_22 := 2.0 * ((rB12 * rB12 * rWeight_Q_P) + (rB22 * rB22 * rWeight_Q_T) + rWeight_R_TCV);

(* Single-Step Projected Newton Optimization *)
IF rHessian_11 > 0.001 THEN
    rDelta_u1_Optimal := - (2.0 * ((rB11 * rWeight_Q_P * rPred_x1_free) + (rB21 * rWeight_Q_T * rPred_x2_free))) / rHessian_11;
ELSE
    rDelta_u1_Optimal := 0.0;
END_IF;

IF rHessian_22 > 0.001 THEN
    rDelta_u2_Optimal := - (2.0 * ((rB12 * rWeight_Q_P * rPred_x1_free) + (rB22 * rWeight_Q_T * rPred_x2_free))) / rHessian_22;
ELSE
    rDelta_u2_Optimal := 0.0;
END_IF;

(* === SECTION 4: 32-BIT COMPREHENSIVE DIAGNOSTIC ALARM & STATUS REGISTERS === *)
wDiagnosticAlarms := 16#00000000;
IF rP_VotedCavern > 82.0 THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000001; (* Bit 0: Cavern Overpressure High *)
END_IF;
IF rP_VotedCavern < 35.0 THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000002; (* Bit 1: Cavern Depletion Low Warning *)
END_IF;
IF rT_LetdownExitEstimated <= 2.0 THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000004; (* Bit 2: Joule-Thomson Cryo-Freezing Warning *)
END_IF;
IF rT_LetdownExitEstimated <= -15.0 THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000008; (* Bit 3: Critical Cryo Ice Hazard Trip Level *)
END_IF;
IF ABS(rThermalStressRate) > rMaxThermalRate_C_Min THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000010; (* Bit 4: Recuperator Thermal Stress Gradient Exceeded *)
END_IF;
IF bFault_P_A OR bFault_P_B OR bFault_P_C THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000020; (* Bit 5: Wellhead Pressure 2oo3 Sensor Discrepancy *)
END_IF;
IF bFault_T_A OR bFault_T_B OR bFault_T_C THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000040; (* Bit 6: Recuperator Temperature 2oo3 Discrepancy *)
END_IF;
IF NOT bEmergencyTripPB THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000080; (* Bit 7: SIL-3 E-Stop Circuit Opened *)
END_IF;
IF (bFault_P_A AND bFault_P_B) OR (bFault_P_B AND bFault_P_C) OR (bFault_P_C AND bFault_P_A) THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000100; (* Bit 8: Loss of Dual Redundant Pressure Channels *)
END_IF;
IF rP_HeaderActual > 52.0 THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000200; (* Bit 9: Header Manifold High Pressure Trip Permissive *)
END_IF;
IF rT_FlueGas_In > 585.0 THEN
    wDiagnosticAlarms := wDiagnosticAlarms OR 16#00000400; (* Bit 10: Flue Gas Overtemperature Recuperator Hazard *)
END_IF;

(* === SECTION 5: SAFETY INTERLOCK HARDWIRED MASTER TRIP SUPERVISOR === *)
IF (NOT bEmergencyTripPB) OR (rP_VotedCavern > 86.0) OR (rT_LetdownExitEstimated < -15.0) OR (rP_HeaderActual > 54.0) THEN
    bTripActive := TRUE;
    bSystemReady := FALSE;
    iState := 99; (* FORCE SIL-3 EMERGENCY ISOLATION STATE *)
END_IF;

(* === SECTION 6: MULTI-STAGE CYBER-PHYSICAL STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & DEPRESSURIZED STATE *)
        wSystemStatus := 16#0000;
        bTripActive := FALSE;
        bSystemReady := FALSE;
        rPCV_CurrentPos := 0.0;
        rTCV_CurrentPos := 100.0; (* Thermal bypass fully open to safeguard heat exchanger *)
        tStateTimer(IN := FALSE);
        rWarmupProgress_Pct := 0.0;

        IF bEnable AND bEmergencyTripPB THEN
            iState := 10; (* Proceed to sensor validation *)
        END_IF;

    10: (* SENSOR INTEGRITY VALIDATION & PRE-START WARMUP *)
        wSystemStatus := 16#000A;
        tStateTimer(IN := TRUE, PT := T#3S);

        IF (bFault_P_A AND bFault_P_B) OR (bFault_P_B AND bFault_P_C) OR (bFault_P_C AND bFault_P_A) THEN
            (* Double pressure failure prevents startup *)
            iState := 99;
        ELSIF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            IF bFault_P_A OR bFault_P_B OR bFault_P_C OR bFault_T_A OR bFault_T_B OR bFault_T_C THEN
                iState := 50; (* Transition directly to degraded mode *)
            ELSE
                iState := 20; (* Proceed to controlled letdown ramp *)
            END_IF;
        END_IF;

    20: (* CONTROLLED WELLHEAD PRESSURE LETDOWN RAMP *)
        wSystemStatus := 16#0014;
        (* Slew-rate constrained pressure letdown ramping *)
        IF rP_HeaderActual < (rP_HeaderSetpoint * 0.85) THEN
            rPCV_CurrentPos := rPCV_CurrentPos + (rMaxSlewPCV_PerSec * rCycleTime_Sec);
            IF rPCV_CurrentPos > 30.0 THEN
                rPCV_CurrentPos := 30.0; (* Limit initial pressurization stroke *)
            END_IF;
        ELSE
            iState := 30; (* Proceed to recuperator warmup *)
        END_IF;

    30: (* RECUPERATOR THERMAL SOAK & CONTROLLED GRADIENT WARMUP *)
        wSystemStatus := 16#001E;
        (* Regulate header pressure while gently modulating bypass damper *)
        IF rThermalStressRate < rMaxThermalRate_C_Min THEN
            rTCV_CurrentPos := rTCV_CurrentPos - (rMaxSlewTCV_PerSec * 0.5 * rCycleTime_Sec);
            IF rTCV_CurrentPos < 20.0 THEN
                rTCV_CurrentPos := 20.0;
            END_IF;
        ELSE
            (* Back off bypass closing if thermal rate exceeds limit *)
            rTCV_CurrentPos := rTCV_CurrentPos + (rMaxSlewTCV_PerSec * 0.8 * rCycleTime_Sec);
        END_IF;

        (* Evaluate warmup readiness criteria *)
        IF (rT_AirToTurbine >= (rTarget_TurbineTemp * 0.80)) AND (rP_HeaderActual >= (rP_HeaderSetpoint * 0.92)) THEN
            bSystemReady := TRUE;
            iState := 40; (* Handover to full Model Predictive Control *)
        END_IF;

    40: (* FULL CLOSED-LOOP COGENERATION & STATE-SPACE MPC *)
        wSystemStatus := 16#0028;
        bSystemReady := TRUE;

        (* Apply bounded optimal MPC control updates *)
        rPCV_CurrentPos := rPCV_CurrentPos + (rDelta_u1_Optimal * rCycleTime_Sec);
        rTCV_CurrentPos := rTCV_CurrentPos + (rDelta_u2_Optimal * rCycleTime_Sec);

        (* If thermal stress warning triggers, override bypass to cool down *)
        IF ABS(rThermalStressRate) > rMaxThermalRate_C_Min THEN
            rTCV_CurrentPos := rTCV_CurrentPos + (2.0 * rCycleTime_Sec);
        END_IF;

        (* Check if sensor failure has occurred during operation *)
        IF bFault_P_A OR bFault_P_B OR bFault_P_C OR bFault_T_A OR bFault_T_B OR bFault_T_C THEN
            iState := 50; (* Degraded 1oo2 mode *)
        END_IF;

        (* Normal shutdown requested *)
        IF NOT bEnable THEN
            iState := 60;
        END_IF;

    50: (* DEGRADED 1oo2 FAULT-RESILIENT OPERATION *)
        wSystemStatus := 16#0032;
        bSystemReady := TRUE;

        (* In degraded mode, apply conservative tuning gains (50% reduction in delta movement) *)
        rPCV_CurrentPos := rPCV_CurrentPos + (rDelta_u1_Optimal * 0.5 * rCycleTime_Sec);
        rTCV_CurrentPos := rTCV_CurrentPos + (rDelta_u2_Optimal * 0.5 * rCycleTime_Sec);

        (* Critical failure of two sensors requires controlled abort *)
        IF (bFault_P_A AND bFault_P_B) OR (bFault_P_B AND bFault_P_C) OR (bFault_P_C AND bFault_P_A) THEN
            iState := 60;
        END_IF;

        IF NOT bEnable THEN
            iState := 60;
        END_IF;

    60: (* NORMAL CONTROLLED SHUTDOWN & THERMAL PURGE *)
        wSystemStatus := 16#003C;
        bSystemReady := FALSE;

        (* Controlled ramp down of PCV and opening of TCV bypass *)
        rPCV_CurrentPos := rPCV_CurrentPos - (rMaxSlewPCV_PerSec * 1.5 * rCycleTime_Sec);
        rTCV_CurrentPos := rTCV_CurrentPos + (rMaxSlewTCV_PerSec * 1.5 * rCycleTime_Sec);

        IF rPCV_CurrentPos <= 0.0 THEN
            rPCV_CurrentPos := 0.0;
            rTCV_CurrentPos := 100.0;
            iState := 0; (* Return to idle *)
        END_IF;

    99: (* EMERGENCY FAST SHUTDOWN & SIL-3 ISOLATION *)
        wSystemStatus := 16#0063;
        bTripActive := TRUE;
        bSystemReady := FALSE;
        rPCV_CurrentPos := 0.0;   (* Immediate crash shutoff of letdown valve *)
        rTCV_CurrentPos := 100.0; (* Full open bypass to protect recuperator from thermal shock *)

        (* Require deliberate enable reset and push button clearing to exit trip *)
        IF bEmergencyTripPB AND (NOT bEnable) THEN
            bTripActive := FALSE;
            iState := 0;
        END_IF;

